/**
 * ============================================================================
 * POLICES SCOLAIRES POUR LES PDF PUPPETEER — incorporées en base64
 * ============================================================================
 *
 * ⭐ V12 (2026-09-22) : les lignes calligraphiques insérées dans les fiches et
 *    les épreuves utilisent les polices scolaires Playwrite FR Moderne /
 *    Playwrite FR Trad (cursives françaises, OFL) et Comic Neue (script).
 *
 *    Les <link> Google Fonts des templates ne sont PAS fiables sur Railway
 *    (réseau sortant incertain / latence vs networkidle0) → les polices sont
 *    EMBARQUÉES en data-URI dans chaque PDF : rendu déterministe, sans
 *    dépendance réseau. (≈ 58 Ko par police, générées depuis
 *    apps/web-app/public/fonts — script scripts/gen2d/make-pdf-fonts.py)
 * ============================================================================
 */

/** Bloc <style> à insérer dans le <head> des templates PDF. */
export const SCHOOL_FONTS_CSS = `
@font-face { font-family: 'Playwrite FR Moderne'; src: url(data:font/woff2;base64,) format('woff2'); font-weight: 400; font-style: normal; font-display: block; }
@font-face { font-family: 'Playwrite FR Trad'; src: url(data:font/woff2;base64,) format('woff2'); font-weight: 400; font-style: normal; font-display: block; }
@font-face { font-family: 'Comic Neue'; src: url(data:font/woff2;base64,) format('woff2'); font-weight: 400; font-style: normal; font-display: block; }
`;
